const hints={slowrise:'Press and hold to make a dent. Release and give it a few lovely seconds to rise.',popit:'Press or sweep across the bubbles. Flip your pop garden to reset.',bubblewrap:'Drag a fingertip over the bubbles for a little trail of pops.',slime:'Grab the slime and pull. Try a long stretch, then let go.',sand:'Rake with your finger. Switch to a stamp to leave little impressions.',jelly:'Press, pull and flick the jelly. It wobbles long after you let go.',water:'Touch or sweep to send ripples across the water.',beads:'Hold and squeeze. The jelly beads bulge through the mesh.',spinner:'Swipe around the centre, then let it spin down.',putty:'Pull and knead the putty. Choose a stamp to leave a little mark.',kaleidoscope:'Draw circles to turn the glass. Every movement makes a new pattern.',cube:'Swipe left or right to fold. Watch the hinges turn.',glitter:'Swirl with your finger, then watch the glitter settle slowly.',zipper:'Drag the zip up and down. Slide the switch. Press the big button.',balloon:'Grab, pinch and stretch. This balloon always bounces back.',music:'Turn the handle in a circle to wind a little melody.',mochi:'Press either twin. Drag to stretch their soft little cheeks.',magnets:'Drag a moon pebble near another. They snap together into little chains.',projector:'Drag across the sky to turn it. Tap stars to connect your own constellation.'};status.textContent=hints[kind]||'Touch and explore.';
const palette=['#e9a6c8','#b6ace8','#96d5cc','#f0d08b','#9ebfe7'];const sparkles=Array.from({length:150},()=>({x:245+Math.random()*150,y:90+Math.random()*250,vx:0,vy:Math.random()*7,r:1+Math.random()*2}));const stars=Array.from({length:75},(_,i)=>({x:30+(i*101)%580,y:30+(i*83)%330,r:i%5===0?2.5:1}));
